UICrateSprite=function(game,gameController,dustEmitter){Phaser.Sprite.call(this,game,0,0,'game','crate0-0');this.gameController=gameController;this.dustEmitter=dustEmitter;this.game.physics.p2.enable(this);this.body.allowSleep=false;this.body.kinematic=true;this.body.setRectangle(Constants.CRATE.WIDTH.px,Constants.CRATE.HEIGHT.px);this.body.setCollisionGroup(UIUtils.crateCollisionGroup);this.body.collides([UIUtils.fragmentCollisionGroup,UIUtils.crateCollisionGroup]);this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.theme=0;this.contentFrame=0;this.kill();};UICrateSprite.prototype=Object.create(Phaser.Sprite.prototype);UICrateSprite.prototype.constructor=UICrateSprite;UICrateSprite.prototype.setTheme=function(theme){this.theme=theme;this.frameName='crate'+this.theme+'-'+this.contentFrame};UICrateSprite.prototype.update=function(){if(!this.exists){return;}var crate=this.gameController.getCollectible(this.crateId);if(crate){this.smoothedX=(this.body.x+UIUtils.mpx(crate.getX()))/2.0;this.smoothedY=(this.body.y+UIUtils.mpx(crate.getY()))/2.0;this.smoothedRotation=(this.body.rotation+crate.getRotation())/2.0;}this.body.x=this.smoothedX;this.body.y=this.smoothedY;this.body.rotation=this.smoothedRotation;};UICrateSprite.prototype.spawn=function(x,y,rotation,contentFrame,crateId,animate){this.contentFrame=contentFrame;this.reset(x,y);this.frameName='crate'+this.theme+'-'+this.contentFrame;this.body.rotation=rotation;this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.smoothedX=x;this.smoothedY=y;this.smoothedRotation=rotation;if(animate){this.game.sound.play('crateSpawn');this.scale.setTo(0.01,0.01);this.spawnTween=this.game.add.tween(this.scale).to({x:UIConstants.GAME_ASSET_SCALE,y:UIConstants.GAME_ASSET_SCALE},UIConstants.CRATE_SPAWN_TIME,UIUtils.easingCubicBezier(0.01,1.5,1.5,1),true);this.spawnTween.onComplete.add(function(){this.game.sound.play('crateLand');this.dustEmitter.spawn(this.x,this.y);},this);}this.crateId=crateId;};UICrateSprite.prototype.getExtraPositionInfo=function(){return null;};UICrateSprite.prototype.remove=function(){if(this.spawnTween){this.spawnTween.stop();}this.kill();};UICrateSprite.prototype.retire=function(){if(this.spawnTween){this.spawnTween.stop();}this.kill();};